      // Canonical normal vector so parallel edges between the same pair separate cleanly
      var canonDx = m.source < m.target ? dx : -dx
      var canonDy = m.source < m.target ? dy : -dy
      var nx = -canonDy / dist
      var ny = canonDx / dist
